<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElButton,ElInput,ElSelect,ElOption,ElDialog,ElInputNumber,ElCheckbox,ElTimeSelect} from 'element-plus'
import {api,type Account} from '../../api'
import {confirmAction} from '../../shared/confirm'
import AdminListPager from '../../shared/list/AdminListPager.vue'
import AdminStatusBadge from '../../shared/list/AdminStatusBadge.vue'
import {useCurrentPageSelection} from '../../shared/list/useCurrentPageSelection'
interface Store {id:string;name:string;city:string;latitude:number|null;longitude:number|null}
import {useShippingConfig} from './use-shipping-config'
import {blankZone,money,type Zone,type Point} from './types'
import {zoneIssue} from './rule-validation.mjs'
import DeliveryFenceMap from './DeliveryFenceMap.vue'
import FenInput from './FenInput.vue'
import ShippingTrial from './ShippingTrial.vue'
import OperationMessage from './operation-message.vue'
import './shipping.css'
const props=defineProps<{account:Account}>(),route=useRoute(),state=useShippingConfig(),{config,loading,busy,error,notice,needsRead}=state
const storeId=computed(()=>String(route.params.storeId)),store=ref<Store|null>(null),permitted=computed(()=>props.account.permissionCodes.includes('settlement.shipping.manage'))
const warehouse=computed<Point|null>(()=>store.value?.latitude!=null&&store.value?.longitude!=null?{latitude:store.value.latitude,longitude:store.value.longitude}:null)
const query=ref(''),status=ref(''),applied=ref(''),appliedStatus=ref(''),page=ref(1),size=ref(20)
const filtered=computed(()=>config.value?.zones.filter(z=>z.storeId===storeId.value&&z.name.includes(applied.value)&&(appliedStatus.value===''||String(z.enabled)===appliedStatus.value))||[])
const rows=computed(()=>filtered.value.slice((page.value-1)*size.value,page.value*size.value)),selection=useCurrentPageSelection(()=>rows.value,z=>z.id)
const editor=ref<Zone|null>(null),issue=computed(()=>editor.value?zoneIssue(editor.value):'')
const trialOpen=ref(false);let epoch=0
function search(){applied.value=query.value.trim();appliedStatus.value=status.value;page.value=1}
function edit(z?:Zone){editor.value=z?JSON.parse(JSON.stringify(z)):{...blankZone(storeId.value),center:warehouse.value};error.value=''}
async function save(){if(!editor.value||issue.value){error.value=issue.value;return}const{id,...body}=editor.value;if(await state.write(id?`zones/${encodeURIComponent(id)}`:'zones',id?'PUT':'POST',body))editor.value=null}
async function remove(z:Zone){if(await confirmAction(`删除围栏“${z.name}”？已生成的订单保持原配送快照。`,{confirmButtonText:'删除围栏'}))await state.write(`zones/${encodeURIComponent(z.id)}`,'DELETE',{})}
async function bulk(enabled:boolean){if(selection.selectedIds.value.length&&await confirmAction(`确认${enabled?'启用':'停用'}所选 ${selection.selectedIds.value.length} 个围栏？`)){await state.write('bulk','POST',{resource:'zones',ids:selection.selectedIds.value,enabled});selection.clear()}}
async function load(){const current=++epoch;store.value=null;await state.load();try{const result=await api<Store>(`/shipping/stores/${encodeURIComponent(storeId.value)}`);if(current===epoch)store.value=result}catch(e){if(current===epoch)error.value=e instanceof Error?e.message:'前置仓读取失败，请重试。'}}
watch(state.recoveryCounter,()=>{editor.value=null;selection.clear()})
watch(()=>[storeId.value,props.account.accountId,props.account.permissionCodes.join(',')],()=>{epoch++;state.reset();editor.value=null;trialOpen.value=false;selection.clear();if(permitted.value)load()},{immediate:true})
</script>
<template><section class="page-content shipping-page"><header class="page-heading"><div><h1>{{store?.name||'前置仓'}} · 配送规则</h1><p>排除区优先，服务区按优先级由小到大匹配。经营包邮由前置仓承担。</p></div><div class="inline-fields"><RouterLink to="/stores"><ElButton>返回前置仓</ElButton></RouterLink><ElButton type="primary" :disabled="!config||!store||busy||needsRead" @click="edit()">新增配送围栏</ElButton></div></header><p v-if="!permitted" role="alert">当前账号没有前置仓配送配置权限。</p><p v-if="loading" role="status">正在读取配送规则…</p><p v-if="error" class="error" role="alert">{{error}} <ElButton :disabled="busy" @click="load">重新读取</ElButton></p><p v-if="notice" class="notice" role="status">{{notice}}</p><template v-if="config&&!loading"><form class="panel inline-fields admin-list-filters" @submit.prevent="search"><label>围栏名称<ElInput v-model="query" aria-label="围栏名称" maxlength="100"/></label><label>围栏状态<ElSelect v-model="status" aria-label="围栏状态" style="width:150px"><ElOption label="全部状态" value=""/><ElOption label="已启用" value="true"/><ElOption label="已停用" value="false"/></ElSelect></label><ElButton type="primary" native-type="submit">查询</ElButton><ElButton @click="query='';status='';search()">重置</ElButton></form><div class="rule-toolbar"><div class="inline-fields"><span>已选 {{selection.selectedIds.value.length}} 项</span><ElButton :disabled="!selection.selectedIds.value.length||busy||needsRead" @click="bulk(true)">批量启用</ElButton><ElButton :disabled="!selection.selectedIds.value.length||busy||needsRead" @click="bulk(false)">批量停用</ElButton></div><ElButton :disabled="busy" @click="trialOpen=true">地图运费试算</ElButton></div><div class="panel table-wrap admin-list-table" tabindex="0" aria-label="配送围栏列表"><table><thead><tr><th><input type="checkbox" aria-label="选择当前页全部围栏" :checked="selection.allSelected.value" :indeterminate="selection.indeterminate.value" @change="selection.togglePage(($event.target as HTMLInputElement).checked)"></th><th>围栏</th><th>形状 / 优先级</th><th>配送费</th><th>起送 / 包邮</th><th>配送时段</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="z in rows" :key="z.id"><td><input type="checkbox" :aria-label="`选择 ${z.name}`" :checked="selection.selectedIds.value.includes(z.id)" @change="selection.toggle(z.id,($event.target as HTMLInputElement).checked)"></td><td>{{z.name}}</td><td>{{({CIRCLE:'圆形服务区',POLYGON:'多边形服务区',EXCLUDE:'排除区'})[z.kind]}}<small>{{z.kind==='EXCLUDE'?'最高优先级':`优先级 ${z.priority}`}}</small></td><td>{{z.kind==='EXCLUDE'?'不可配送':money(z.feeFen)}}<small v-if="z.kind!=='EXCLUDE'&&z.feeMode==='DISTANCE'">首 {{z.firstMeters}} 米；续 {{z.extraMeters}} 米 {{money(z.extraFeeFen)}}</small></td><td>{{z.kind==='EXCLUDE'?'—':`${money(z.minimumFen)} / ${money(z.freeThresholdFen)}`}}</td><td>{{z.kind==='EXCLUDE'?'全天':`${z.startTime}–${z.endTime}`}}</td><td><AdminStatusBadge :status="z.enabled?'ACTIVE':'DISABLED'" :label="z.enabled?'已启用':'已停用'" :tone="z.enabled?'success':'neutral'"/></td><td><ElButton link type="primary" :disabled="busy||needsRead" @click="edit(z)">编辑</ElButton><ElButton link type="danger" :disabled="busy||needsRead" @click="remove(z)">删除</ElButton></td></tr><tr v-if="!rows.length"><td colspan="8">尚未配置服务围栏。新增并启用后才能配送到家。</td></tr></tbody></table></div><AdminListPager :page="page" :page-size="size" :total="filtered.length" @change="(p,s)=>{page=p;size=s}"/></template>
<ElDialog :model-value="!!editor" :title="editor?.id?'编辑配送围栏':'新增配送围栏'" width="min(1000px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" @update:model-value="v=>{if(!v&&!busy)editor=null}"><template v-if="editor"><OperationMessage :error="error" :needs-read="needsRead" :busy="busy" @reload="state.load"/><div class="rule-fields"><label>围栏名称<ElInput v-model="editor.name" maxlength="100" :disabled="busy"/></label><label>围栏类型<ElSelect v-model="editor.kind" :disabled="busy"><ElOption label="圆形服务区" value="CIRCLE"/><ElOption label="多边形服务区" value="POLYGON"/><ElOption label="排除区" value="EXCLUDE"/></ElSelect></label><label v-if="editor.kind==='CIRCLE'">配送半径（米）<ElInputNumber v-model="editor.radiusMeters" :min="1" :max="50000" :precision="0" :disabled="busy"/></label><label v-if="editor.kind!=='EXCLUDE'">优先级（数字越小越优先）<ElInputNumber v-model="editor.priority" :min="1" :max="9999" :precision="0" :disabled="busy"/></label></div><DeliveryFenceMap v-model="editor" :warehouse="warehouse" :disabled="busy" :context-key="`${storeId}:${account.accountId}:${editor.id}`"/><div v-if="editor.kind!=='EXCLUDE'" class="rule-fields"><label>计费方式<ElSelect v-model="editor.feeMode" :disabled="busy"><ElOption label="固定配送费" value="FIXED"/><ElOption label="按距离计费" value="DISTANCE"/></ElSelect></label><FenInput v-model="editor.feeFen" :label="editor.feeMode==='FIXED'?'配送费':'首段配送费'" :disabled="busy"/><label v-if="editor.feeMode==='DISTANCE'">首段距离（米）<ElInputNumber v-model="editor.firstMeters" :min="1" :precision="0" :disabled="busy"/></label><label v-if="editor.feeMode==='DISTANCE'">续段距离（米）<ElInputNumber v-model="editor.extraMeters" :min="1" :precision="0" :disabled="busy"/></label><FenInput v-if="editor.feeMode==='DISTANCE'" v-model="editor.extraFeeFen" label="续段配送费" :disabled="busy"/><FenInput v-model="editor.minimumFen" label="起送金额" :disabled="busy"/><FenInput v-model="editor.freeThresholdFen" label="经营包邮门槛" nullable :disabled="busy"/><label>配送开始时间<ElTimeSelect v-model="editor.startTime" start="00:00" end="23:55" step="00:05" :disabled="busy"/></label><label>配送结束时间<ElTimeSelect v-model="editor.endTime" start="00:00" end="23:55" step="00:05" :disabled="busy"/></label></div><ElCheckbox v-model="editor.enabled" :disabled="busy">启用围栏</ElCheckbox><p v-if="issue" role="status">{{issue}}</p></template><template #footer><ElButton :disabled="busy" @click="editor=null">取消</ElButton><ElButton type="primary" :loading="busy" :disabled="!!issue||needsRead" @click="save">保存围栏</ElButton></template></ElDialog>
<ElDialog v-model="trialOpen" title="地图运费试算" width="min(850px,94vw)" :close-on-click-modal="false"><ShippingTrial v-if="trialOpen" :store-id="storeId" :city="store?.city" mode="DELIVERY"/><template #footer><ElButton @click="trialOpen=false">关闭</ElButton></template></ElDialog></section></template>
